const gId = "gId";
let lapse = 0;    // mouse timer

function setup() {
	createCanvas(1112, 834, WEBGL);
	//normalMaterial();

	//shader
	sh = createShader(vert,frag);
	this.shader(sh);
	sh.setUniform("u_resolution", [width,height]);
	sh.setUniform("u_pixelDensity", pixelDensity());
	sh.setUniform("u_lightDir", [1,-1,0.5]);
	noStroke();

	setCol("#DDDDDD");
}

function draw() {
	let radius = min(height, width) * 0.6;
	background(0);
	orbitControl(200);
	rotateX(frameCount/45);
	rotateY(frameCount/200);
	MyTorus(120,50,radius,radius*0.9);	
}


function MyTorus(row, colum, inRadius, outRadius)
{
	const scale = inRadius;
	const outRadiusRatio = outRadius/inRadius;
	//const gId = `MyTorus|${row}|${colum}|${outRadiusRatio}|`;
	if (this._renderer.geometryInHash(gId) && frameCount % 2 == 0)
	{
		this._renderer.drawBuffersScaled(gId,scale, scale, scale);
		return;
	}


	const noiseScale = 50;
	const frameRatio = (frameCount % 200 ) / 200;

	let geometry = new p5.Geometry(colum, row);
	let mat = new p5.Matrix();

	for(let i = 0; i <= row; i++)
	{
		let rad = TAU / row * i;
		let waveVal = sin(rad * 4 + frameRatio * TAU ) + sin(rad * 1 + frameRatio * TAU * 3) * 0.7  + sin(rad * 10 - frameRatio * TAU * 2) * 0.5;
		waveVal /= 2.2;
		let waveStrength = (pow(sin(frameRatio * TAU), 2) + 0.1);
		var radius = outRadiusRatio * (1 + waveVal * waveStrength);

		for(let k = 0; k <= colum; k++)
		{
			let rad2 = TAU / colum * k;
			// make matrix
			mat = p5.Matrix.identity(); 
			mat.rotateY(rad);
			mat.translate([1, 0, 0]);
			mat.rotateZ(rad2);
			mat.translate([0, radius, 0]);
			//pos
			let pos = ApplyP5MatrixToVector(mat, createVector(0,0,0));
			let vertIndex = k + (colum + 1) * i;
			geometry.vertices[vertIndex] = pos;
			geometry.uvs[vertIndex] = [map(k, 0, colum, 0, 1), map(i, 0, row, 0, 1)];
		}
	}

	geometry.computeFaces();
	//フェースの修正
	let faces = geometry.faces;
	for(let i = 0; i < faces.length; i++)
	{
		let face = faces[i];
		for(let j = 0; j < face.length; j++)
		{
			let maxIndexNum =  row *(colum + 1);
			face[j] = face[j] >= maxIndexNum ?  face[j] % maxIndexNum : face[j];
		}
	}
	geometry.computeNormals().averageNormals();
	geometry._makeTriangleEdges()._edgesToVertices();//make stroke vert
	this._renderer.createBuffers(gId, geometry);
	this._renderer.drawBuffersScaled(gId,scale, scale, scale);
}

