// === Tab: MatUtil ===
function ApplyP5MatrixToVector(_matrix, _posVector)
{
	let m = getArrayFromP5Mat(_matrix);
	let x = _posVector.x;
	let y = _posVector.y;
	let z = _posVector.z;
	let w = 1;
	let output = [];
	for(let i = 0; i < 4; i ++)
	{
		output.push(m[i] * x +  m[i+4] * y + m[i+8] * z + m[i+12] * w);
	}
	return createVector(output[0], output[1], output[2]);
}

function getArrayFromP5Mat(_matrix)
{
	var m = _matrix.mat4;
	if(m.length != 16)
	{
		print("no matrix");
		print("mat4Array has = " + m);
		return false;
	}
	return m;
}



// === Tab: Shader ===
//_col  color or number
function setCol(_col,_shader = sh,_uniformName = "u_col")
{
	const col = typeof (_col) == "string" ? color(_col) : _col;
	let　colArray = col._array;
	colArray.pop();
	_shader.setUniform(_uniformName,colArray);
}

var vert = `
		precision highp float;

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;
		varying vec4 var_centerGlPosition;//原点

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;
		uniform float u_time;


    void main() {
      vec3 pos = aPosition;
			vec4 posOut = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);
      gl_Position = posOut;

      // set out value
      var_vertPos      = pos;
      var_vertNormal   =  aNormal;
      var_vertTexCoord = aTexCoord;
			var_centerGlPosition = uProjectionMatrix * uModelViewMatrix * vec4(0., 0., 0.,1.0);
    }
`;


var frag = `

precision highp float;

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;
uniform vec3 u_lightDir;
uniform vec3 u_col;
uniform mat3 uNormalMatrix;
uniform float u_pixelDensity;
uniform sampler2D u_tex;

//attributes, in
varying vec4 var_centerGlPosition;
varying vec3 var_vertNormal;
varying vec2 var_vertTexCoord;

float random (in vec2 st) {
   	highp float a = 12.9898;
    highp float b = 78.233;
    highp float c = 43758.5453;
    highp float dt= dot(st.xy ,vec2(a,b));
    highp float sn= mod(dt,3.14);
    return fract(sin(sn) * c);
}

float noise(vec2 st) {
    vec2 i = vec2(0.);
		i = floor(st);
    vec2 f = vec2(0.);
		f = fract(st);
    vec2 u =  vec2(0.);
		u = f*f*(3.0-2.0*f);
    return mix( mix( random( i + vec2(0.0,0.0) ),
                     random( i + vec2(1.0,0.0) ), u.x),
                mix( random( i + vec2(0.0,1.0) ),
                     random( i + vec2(1.0,1.0) ), u.x), u.y);
}

void main() {

    vec2 st = gl_FragCoord.xy/u_resolution.xy;
		st.x *= u_resolution.x/u_resolution.y;

		vec2 centerPos = var_centerGlPosition.xy/var_centerGlPosition.w;//スクリーン変換
		centerPos = (centerPos + 1.0)*.5*u_pixelDensity;//gl_FragCoordと座標を合わせる pixelDensityによって係数が変化する
		centerPos.x *= u_resolution.x/u_resolution.y;//gl_FragCoordと座標を合わせる

		vec3 vertNormal = normalize(uNormalMatrix * var_vertNormal);
    float dot = dot(vertNormal,-normalize(u_lightDir));
    dot = pow(dot *.5 + .5,1.) ;

    float noise1 = noise((st-centerPos)*700.);
		float tone = step(noise1,dot);
		vec3 col = u_col * tone + (u_col-0.12 + var_vertNormal * 0.5) * (1.-tone);

		gl_FragColor = vec4(col,1.);
}

`;

